package com.rappistream.orderprocessor.infrastructure.jpa;  import jakarta.persistence.Column; import jakarta.persistence.Embeddable;  @Embeddable public class OrderItemEmbeddable {      @Column(name = "sku", length = 64, nullable = false)     private String sku;      @Column(name = "quantity", nullable = false)     private int quantity;      public OrderItemEmbeddable() {     }      public OrderItemEmbeddable(String sku, int quantity) {         this.sku = sku;         this.quantity = quantity;     }      public String getSku() { return sku; }     public void setSku(String sku) { this.sku = sku; }     public int getQuantity() { return quantity; }     public void setQuantity(int quantity) { this.quantity = quantity; } }
